/**
 * Data URI for an <image href> inside an SVG, or null if the code is unknown.
 *
 * Returns null rather than throwing on purpose: a share card missing its badge
 * is a degraded card, but a card that fails to render is a broken link preview
 * on someone's LinkedIn post. Callers should branch and omit the <image>.
 */
export function badgeDataUri(code: string | null | undefined): string | null {
  if (!code) return null;
  const b64 = BADGE_B64[code.trim().toUpperCase()];
  return b64 ? "data:image/png;base64," + b64 : null;
}
